INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_ADJECTIVE','Household');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_APPA_BIO','Appa is a male orange tabby from Bonnie''s first litter. His name comes from an arrow-shaped marking on his back. Playful and affectionate toward one of the sisters, he especially enjoys playing with Oscar.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_APPA_EFFECT','+1 Culture; +1 Food; +1 Production.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_APPA_FAMILY','Bonnie''s first litter, with Loki and Kuro. Especially enjoys Oscar. With Loki and Oscar, activates Sister''s Bed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_APPA_GENDER','Male');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_APPA_NAME','Appa');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_APPA_TRAIT','Arrowback Playfulness');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_ATTACKED_1','You bring fighting to our door? My family will be protected.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN','Austin — King of the House');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_BIO','Austin is the oldest cat and the first member of the household, adopted in 2013. White and long-haired, he is the affectionate King of the House. He is extremely vocal when asking for pats and loves attention. Austin leads the civilization; he never spawns as a House Cat unit.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_EFFECT','Leader of the household; always counted as its first member.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_FAMILY','The first member of the same growing household. Luna tolerates Austin.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_GENDER','Male');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_HEADING_1','The First Cat');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_LIVED','Adopted in 2013');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_NAME','Austin');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_SUBTITLE','King of the House');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_TEXT_1','Austin is the oldest cat and the first member of the household, adopted in 2013. White and long-haired, he is the affectionate King of the House. He is extremely vocal when asking for pats and loves attention. Austin leads the civilization; he never spawns as a House Cat unit.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_TITLES_1','King of the House');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_AUSTIN_TRAIT','King of the House');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BIO','Biography');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BONDS','Family Bonds');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BONDS_PEDIA','The First Pair: Luna in the current capital gives +1 Culture. Bonnie''s Family: Bonnie with any biological kitten (Appa, Loki, Kuro, Oscar or Boomie) gives +1 Food and +1 Gold, once. Sister''s Bed: Appa, Loki and Oscar together give +1 Happiness and +10% Great Person generation. Mother and Daughter: Charlotte and Sisi together give +1 Happiness and +5% Growth. Bonds are local and independent; their effects end immediately when the combination ends.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BOND_BONNIE_FAMILY','Bonnie''s Family: +1 Food, +1 Gold');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BOND_FIRST_PAIR','The First Pair: +1 Culture');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BOND_MOTHER_DAUGHTER','Mother and Daughter: +1 Happiness, +5% Growth');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BOND_SISTERS_BED','Sister''s Bed: +1 Happiness, +10% Great Person generation');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BONNIE_BIO','A family friend found Bonnie as a stray. The family chose to take her in rather than abandon her. Her arrival became associated with good events, including jobs and promotions. This calico/tortoiseshell-and-white cat was exceptionally friendly and often purred when patted. She became the mother of two litters.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BONNIE_EFFECT','+1 Culture; +1 Gold; +5% Production.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BONNIE_FAMILY','Mother of Appa, Loki, Kuro, Oscar and Boomie. With any one or two of her kittens: +1 Food and +1 Gold, once per city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BONNIE_GENDER','Female');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BONNIE_NAME','Bonnie');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BONNIE_TRAIT','Lucky Arrival');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BOOMIE_BIO','Boomie is a female calico and the runt of Bonnie''s second litter. Extremely affectionate toward the youngest sister, she often sleeps beside her and has developed the habit of licking people. Her small beginnings are part of a life now full of affection.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BOOMIE_EFFECT','+2 Culture; +1 Happiness.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BOOMIE_FAMILY','Bonnie''s second litter, with Oscar. Especially affectionate toward the youngest sister.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BOOMIE_GENDER','Female');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BOOMIE_NAME','Boomie');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_BOOMIE_TRAIT','Little Licker');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CAPACITY','{1_Count}/3 Cats');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CATS','Cats');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHAPTER_1','The First Companion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHAPTER_2','A Lucky Stray');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHAPTER_3','The First Litter');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHAPTER_4','The Second Litter');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHAPTER_5','A Second Rescue');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHAPTER_6','Found Again');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHARLOTTE_BIO','Charlotte, Sisi''s mother, is a long-haired black-and-white cat. Her former family kept her and her kittens in a garage in unsuitable conditions and intended to abandon them. Rescued into a safe home, she now prefers indoor life. Fiercely independent, she decides when she wants affection and may become angry when bothered. She is especially affectionate toward the user. Her ability celebrates the security of home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHARLOTTE_EFFECT','+1 Culture; +5 City Strength; +1 Production.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHARLOTTE_FAMILY','Mother of Sisi. With Sisi: +1 Happiness and +5% Growth. Their earlier suffering never generates rewards.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHARLOTTE_GENDER','Female');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHARLOTTE_NAME','Charlotte');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CHARLOTTE_TRAIT','On Her Terms');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_1','The Family Home');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_10','Safe Haven');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_11','Royal Perch');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_12','Evening Sun');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_2','Sister''s Bed');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_3','Sunny Windowsill');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_4','Warm Blanket');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_5','Purring Hearth');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_6','Quiet Corner');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_7','Golden Cushion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_8','Garden Window');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CITY_9','Treat Cupboard');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CIV','The 11 Cats');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CIV5','The 11 Cats');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CIV5_HEADING_1','Everyone Is Home');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CIV5_TEXT_1','The 11 Cats are eleven real family cats, each with a distinct personality and a place in the same growing household. Austin, adopted in 2013, was first. Luna followed around 2014–2015. Bonnie was rescued as a stray and became mother to Appa, Loki, Kuro, Oscar and Boomie across two litters. Charlotte and her daughter Sisi found safety after unsuitable conditions. Max was once lost and was safely found again.[NEWLINE][NEWLINE]Some were born here. Some were found alone. Some needed a rescue. All eventually had somewhere they belonged. The Household panel tells their stories without turning suffering into a source of rewards.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CIV_PEDIA','The 11 Cats are eleven real family cats, each with a distinct personality and a place in the same growing household. Austin, adopted in 2013, was first. Luna followed around 2014–2015. Bonnie was rescued as a stray and became mother to Appa, Loki, Kuro, Oscar and Boomie across two litters. Charlotte and her daughter Sisi found safety after unsuitable conditions. Max was once lost and was safely found again.[NEWLINE][NEWLINE]Some were born here. Some were found alone. Some needed a rescue. All eventually had somewhere they belonged. The Household panel tells their stories without turning suffering into a source of rewards.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_CLOSE','Close');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_COMPLETE','11 / 11 — Everyone Is Home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_COOLDOWN','Rehoming cooldown: {1_Turns} turns');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_COUNT','The Household — {1_Count} / 11');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_DAWN','Austin, King of the House, your family began in 2013 with a place to belong. Across the ages, ten companions will join you: each with a voice, a history and a favorite place to rest.[NEWLINE][NEWLINE]Build warm homes, welcome those who need them and keep your family safe. May the day come when every place is filled: 11 / 11 — Everyone Is Home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_DEFEAT_1','The house grows quiet... but I hope the ones I love will always find somewhere warm to rest.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_DENOUNCE_1','The household cannot trust such conduct. His Majesty must make this known.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_DOF_1','A fine friendship, don''t you think? Even a king knows the value of good company.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_DOF_ACCEPT_1','Yes. There is a warm place here for a trusted friend.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_DUMMY','Household resident effect');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_DUMMY_HELP','Managed by The Household; cannot be built or purchased.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_EFFECT','Resident effects');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_FAMILY','Family and relationships');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_FLED','{1_Name} has fled the fighting and is hiding. They will return home soon.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_FRIENDLY_1','The household is peaceful today. Come, sit with us. There is always room for another friend.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_FULL','This home already has three Resident Cats.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_GREETING_1','Ah, a visitor! You may approach. His Majesty Austin welcomes those who come in peace. Have you brought suitable offerings?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_HOMES','Homes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_HOSTILE_1','The household needs quiet. Please choose your next words with care.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_HOUSEHOLD','The Household');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_HOUSEHOLD_PEDIA','Austin is always the first member. Ancient: Luna; Classical: Bonnie; Medieval: Appa, Loki, Kuro; Renaissance: Oscar, Boomie; Industrial: Charlotte, Sisi; Modern: Max. Later-era starts immediately welcome every eligible earlier companion. The count includes all joined cats, including those travelling or recovering. At eleven, the milestone is 11 / 11 — Everyone Is Home. It grants no extra empire-wide yields.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_INVALID','This Cat or home is no longer eligible.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_JOINED','{1_Name} has joined the household.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_KING','King of the House');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_KING_HELP','Austin is the leader; he never becomes a civilian unit.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_KURO_BIO','Kuro is a female solid-black cat from Bonnie''s first litter. She is especially attached to the mother, who gives her treats. Kuro becomes vocal when left alone and can be very clingy; familiar company means a great deal to her.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_KURO_EFFECT','+1 Culture; +1 Food; +1 Gold.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_KURO_FAMILY','Bonnie''s first litter, with Appa and Loki. Particularly attached to the mother of the human family.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_KURO_GENDER','Female');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_KURO_NAME','Kuro');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_KURO_TRAIT','Treat Seeker');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LEADER','Austin');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LOCATE','Locate Cat');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LOCKED','This companion has not yet joined.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LOKI_BIO','Loki is a female black-and-white tuxedo cat from Bonnie''s first litter. She is a comfortable, ordinary household companion, particularly affectionate toward a sister. There is a special kind of happiness in feeling completely at home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LOKI_EFFECT','+1 Culture; +1 Food; +1 Happiness.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LOKI_FAMILY','Bonnie''s first litter, with Appa and Kuro. With Appa and Oscar, activates Sister''s Bed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LOKI_GENDER','Female');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LOKI_NAME','Loki');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LOKI_TRAIT','Familiar Comfort');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LOYAL','Always Finds Home');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LOYAL_HELP','Cannot be captured as an enemy reward. Embarks safely; lost companions recover through The Household.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LUNA_BIO','Luna joined around 2014–2015, after Austin. A grey-and-white long-haired cat, she is deeply loyal to one trusted person. She tolerates Austin and Max, but is skittish around strangers and many of the other cats. Her loyalty is quiet, personal and enduring.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LUNA_EFFECT','+1 Culture; +10% Great Person generation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LUNA_FAMILY','Tolerates Austin and Max. In the current capital, she activates The First Pair: +1 Culture.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LUNA_GENDER','Female');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LUNA_NAME','Luna');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_LUNA_TRAIT','One-Person Loyalty');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_MAX_BIO','Max is a male black-and-white cat with pronounced white paws. Originally a stray, he was taken in by someone hoping to find him a loving home. When that person''s circumstances changed because of a move to Indonesia, the family adopted him. Temporarily lost in the process, Max was safely found again. Extremely friendly, he actively asks for pats when a hand comes near his head.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_MAX_EFFECT','+1 Culture; +1 Gold; +1 Happiness.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_MAX_FAMILY','The final companion. Luna tolerates Max. His arrival completes the household: 11 / 11 — Everyone Is Home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_MAX_GENDER','Male');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_MAX_NAME','Max');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_MAX_TRAIT','Found Again');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_NARRATIVE','Household story');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_NEED_CITY','Move this Cat into an owned, non-razing city with a free resident slot.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_NEUTRAL_1','His Majesty is listening. A gentle voice, if you please.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_NOT_JOINED','Not Yet Joined');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_NO_BONDS','No active Family Bonds.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_NO_SPAWN','No safe arrival plot is available; the Cat stays at home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_NO_TURN','Return to normal gameplay during your active turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_OPEN','[ICON_CULTURE] The Household');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_OSCAR_BIO','Oscar is a male black-and-white tuxedo cat from Bonnie''s second litter. Exceptionally friendly, he frequently purrs when patted and sometimes licks people. As a kitten he occasionally growled over his food to discourage the other kittens from taking it. He enjoys playing with Appa.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_OSCAR_EFFECT','+1 Culture; +2 Food.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_OSCAR_FAMILY','Bonnie''s second litter, with Boomie. With Appa and Loki, activates Sister''s Bed: +1 Happiness and +10% Great Person generation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_OSCAR_GENDER','Male');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_OSCAR_NAME','Oscar');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_OSCAR_TRAIT','Purring Appetite');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_PEACE_1','Let us have peace, warm places to rest and no more frightened families.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_PEACE_OFFER_1','Enough. Let every household rest safely again.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_READY','Ready to Settle In.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_RECOVERING','Recovering');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_RECOVERY','No Cat Left Behind');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_RECOVERY_PEDIA','A cat displaced by city loss, destruction, capture or unit removal hides safely and returns after three Standard-speed turns (Quick 2, Epic 5, Marathon 9). If no safe city or plot exists, it remains pending. No yields are earned during recovery. Losing the capital, multiple simultaneous losses and elimination preserve identities without duplicating them. Return requires the human player to own a safe city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_REFUSE_1','His Majesty must decline. Perhaps another offering?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_REHOME','Rehome Cat');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_REHOME_PEDIA','Choose a resident in The Household and click Rehome Cat. Its city effects end and its travelling unit appears safely in or adjacent to that home. The cat cannot Settle In again for ten Standard-speed turns (Quick 7, Epic 15, Marathon 30). Cooldowns belong to identities and survive loading and recovery. A blocked spawn leaves the resident in place until there is room.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_RESIDENT','Settled');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_RETURN','Returns in {1_Turns} turns; waits safely if no home is available.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_RETURNED','{1_Name} has found the way home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SETTLE','Settle In');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SHORT','The 11 Cats');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SISI_BIO','Sisi is Charlotte''s female dark-tortoiseshell kitten. A runt, she experienced health problems connected with her earlier environment. She is now a cherished household member and particularly affectionate with a sister. Her story celebrates resilience, safety and being loved.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SISI_EFFECT','+1 Culture; +1 Happiness; +5% Growth.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SISI_FAMILY','Charlotte''s daughter. With Charlotte: +1 Happiness and +5% Growth. Their earlier suffering never generates rewards.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SISI_GENDER','Female');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SISI_NAME','Sisi');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SISI_TRAIT','Little Survivor');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SPY_1','Soft Paw');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SPY_10','Homeward');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SPY_2','Quiet Purr');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SPY_3','Golden Whisker');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SPY_4','Night Watch');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SPY_5','Velvet Step');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SPY_6','Warm Welcome');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SPY_7','Window Watcher');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_SPY_8','Royal Messenger');
