INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_STATUS','Status');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_STORY','Read Latest Chapter');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_STORY_1','Austin arrived in 2013. Around 2014–2015, Luna followed: a quiet companion whose trust belongs to one special person. There is room beside the King.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_STORY_2','A family friend found Bonnie alone. The family chose to welcome her. Her friendly purr became part of the home, and her arrival was remembered alongside jobs, promotions and happier days.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_STORY_3','Bonnie''s first litter brings Appa, Loki and Kuro into the household: playfulness, familiar comfort and a voice asking for company. Three new lives belong here.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_STORY_4','Oscar and Boomie, Bonnie''s second litter, join the family. A friendly purr, a small kitten beside the youngest sister, and more reasons to make room.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_STORY_5','Charlotte and her kitten Sisi have a safe home now. Their past is treated with care; this chapter celebrates the security, resilience and affection of their lives in the household.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_STORY_6','Max was once lost, and then safely found again. Now his white paws have brought him to this family, and his request for pats has an answer.[NEWLINE][NEWLINE]11 / 11 — Everyone Is Home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_STRATEGY','Develop four to six peaceful cities, build Cat Trees and plan each city''s three resident slots. Culture and Diplomacy are natural victories, with Science a secondary path. Great People, happy homes and genuine WLTKD celebrations reward patient development. Rehoming takes time; the household offers almost no offensive military power.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_TITLE','THE HOUSEHOLD');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_TRADE_1','A generous offering. The King accepts, with a most appreciative purr.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_TRAIT','King of the House');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_TRAIT_HELP','We Love the King Day lasts 25% longer. Throughout history, ten beloved Cats join Austin''s household. Cats may Settle In to owned cities, providing +1 Culture and unique bonuses based on their personalities. Cities may accommodate up to three Resident Cats. Cats can always find their way home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_TRAVELLING','Travelling');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_TREE','Cat Tree');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_TREE_HELP','Replaces Garden. +25% Great Person generation, +1 Culture. Requires no Fresh Water. With at least one Resident Cat: +1 Food, once per city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_TREE_PEDIA','A Cat Tree gives a household places to climb, watch, play and rest. It retains the Garden''s technology, cost and other replacement rules, provides +25% Great Person generation and +1 Culture, and needs no Fresh Water. A resident makes it a lived-in home: +1 Food, whether one, two or three cats share the city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_UNIT','House Cat');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_UNIT_HELP','An untrainable, maintenance-free civilian companion. Move to an owned city and open The Household to Settle In (maximum three residents). Every resident provides +1 Culture and its personal bonus. Cannot attack, work, found cities, upgrade, be purchased, gifted or disbanded. Lost Cats recover and return.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_UNIT_PEDIA','Ten named companions travel as House Cats; Austin is the leader, never an extra unit. The Household registry preserves each identity through travel, residence and recovery. A standard civilian map model represents the companion, with custom portrait and paw-and-crown flag.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_WAIT_COOLDOWN','Wait for the rehoming cooldown to end.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_WAIT_HOME','Waiting safely for a home with space to arrive.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THE11CATS_WAR_1','You threaten my household? Then you leave me no choice. No harm shall come to my family.');
